def parse_time(string: str) ->Optional[mod_datetime.datetime]:
    if not string:
        return None
    m = RE_TIMESTAMP.match(string)
    if not m:
        return None
    year, month, day, hour, minute, second = (int(m.group(i)) for i in range(1, 7))
    microsecond = 0
    if m.group(7):
        frac = m.group(7)[1:]
        frac = frac[:6]
        frac = frac.ljust(6, '0')
        microsecond = int(frac)
    tz_str = m.group(8)
    if tz_str is None:
        tzinfo = None
    elif tz_str == 'Z':
        tzinfo = SimpleTZ()
    else:
        tzinfo = SimpleTZ(tz_str)
    return mod_datetime.datetime(year, month, day, hour, minute, second, microsecond, tzinfo=tzinfo)


def format_time(time: mod_datetime.datetime) ->str:
    if not time:
        return ''
    tzinfo = time.tzinfo
    if tzinfo is None:
        tz_str = ''
    elif isinstance(tzinfo, SimpleTZ):
        if tzinfo.offset == 0:
            tz_str = 'Z'
        else:
            offset = tzinfo.offset
            sign = '+' if offset >= 0 else '-'
            offset = abs(offset)
            tz_str = f'{sign}{offset // 60:02}:{offset % 60:02}'
    else:
        offset = tzinfo.utcoffset(time)
        total_seconds = int(offset.total_seconds())
        sign = '+' if total_seconds >= 0 else '-'
        total_seconds = abs(total_seconds)
        hours, remainder = divmod(total_seconds, 3600)
        minutes = remainder // 60
        tz_str = f'{sign}{hours:02}:{minutes:02}'
    if time.microsecond:
        frac = f'.{time.microsecond:06d}'.rstrip('0')
        return f'{time.year:04}-{time.month:02}-{time.day:02}T{time.hour:02}:{time.minute:02}:{time.second:02}{frac}{tz_str}'
    return f'{time.year:04}-{time.month:02}-{time.day:02}T{time.hour:02}:{time.minute:02}:{time.second:02}{tz_str}'


